<?php
declare(strict_types=1);

$page_title = 'Teaching Planner';
require_once __DIR__ . '/includes/guard.php';
require_once dirname(__DIR__) . '/includes/teaching_planner/init.php';

$service = new TeachingPlannerService($db);
$staffId = tp_actor_id();
$error = '';
$preview = null;
$redirectView = 0;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        tp_require_csrf();
        $action = (string)($_POST['action'] ?? '');
        if ($action === 'generate_preview') {
            $preview = $service->generatePreview($staffId, $_POST);
            $token = bin2hex(random_bytes(16));
            $_SESSION['tp_generation_preview'] = ['token' => $token, 'staff_id' => $staffId, 'created_at' => time(), 'data' => $preview];
        } elseif ($action === 'confirm_generation') {
            $stored = $_SESSION['tp_generation_preview'] ?? null;
            if (!is_array($stored) || !hash_equals((string)($stored['token'] ?? ''), (string)($_POST['preview_token'] ?? '')) || ($stored['staff_id'] ?? '') !== $staffId || time() - (int)($stored['created_at'] ?? 0) > 1800) {
                throw new RuntimeException('The generation preview expired. Generate and review the plan again.');
            }
            $id = $service->savePreview($staffId, $stored['data']);
            unset($_SESSION['tp_generation_preview']);
            tp_flash('success', 'Teaching plan saved as a structured draft.');
            header('Location: teaching_planner.php?view=' . $id); exit;
        } elseif ($action === 'update_item') {
            $planId = (int)($_POST['plan_id'] ?? 0);
            $service->updateItem($staffId, $planId, (int)($_POST['item_id'] ?? 0), $_POST, (int)($_POST['version_lock'] ?? 0));
            tp_flash('success', 'Plan row saved.');
            header('Location: teaching_planner.php?view=' . $planId); exit;
        } elseif (in_array($action, ['submit', 'resubmit'], true)) {
            $planId = (int)($_POST['plan_id'] ?? 0);
            $service->transition($planId, $staffId, $action, trim((string)($_POST['comment'] ?? '')), 'lecturer');
            tp_flash('success', 'Teaching plan submitted for Head of Section review.');
            header('Location: teaching_planner.php?view=' . $planId); exit;
        } elseif ($action === 'create_revision') {
            $id = $service->createRevision((int)($_POST['plan_id'] ?? 0), $staffId);
            tp_flash('success', 'Controlled draft revision created. The approved version remains unchanged.');
            header('Location: teaching_planner.php?view=' . $id); exit;
        } elseif ($action === 'save_lesson') {
            $stages = [];
            foreach ((array)($_POST['stage_name'] ?? []) as $index => $name) {
                $stages[] = ['stage_name' => $name, 'duration_minutes' => $_POST['stage_duration'][$index] ?? 0, 'lecturer_activity' => $_POST['stage_lecturer'][$index] ?? '', 'learner_activity' => $_POST['stage_learner'][$index] ?? '', 'method_resources' => $_POST['stage_resources'][$index] ?? '', 'formative_assessment' => $_POST['stage_assessment'][$index] ?? ''];
            }
            $planId = (int)($_POST['plan_id'] ?? 0);
            $service->saveLessonPlan($staffId, (int)($_POST['item_id'] ?? 0), (int)($_POST['template_version_id'] ?? 0), $_POST, $stages);
            tp_flash('success', 'Lesson Plan draft created and its stage durations validated.');
            header('Location: teaching_planner.php?view=' . $planId); exit;
        } else {
            throw new RuntimeException('Unsupported Teaching Planner action.');
        }
    } catch (Throwable $e) { $error = $e->getMessage(); }
}

require_once __DIR__ . '/includes/nav.php';
$schemaReady = tp_schema_ready($db);
$assignments = $schemaReady ? $service->lecturerAssignments($staffId) : [];
$plans = $schemaReady ? $service->plansForLecturer($staffId) : [];
$viewId = filter_input(INPUT_GET, 'view', FILTER_VALIDATE_INT) ?: 0;
$plan = $viewId ? $service->plan($viewId) : null;
if ($plan && $plan['lecturer_staff_id'] !== $staffId) { $plan = null; $error = 'You are not authorized to view that teaching plan.'; }
$flash = tp_take_flash();
$optionData = [];
foreach ($assignments as $assignment) {
    $structureMap = ['TERM_BASED' => 'term', 'SEMESTER_BASED' => 'semester', 'SHORT_COURSE' => 'short_course'];
    $structure = $structureMap[$assignment['structure_type'] ?? ''] ?? 'annual';
    $optionData[(int)$assignment['assignment_id']] = [
        'templates' => $service->activeTemplates('scheme_of_work', !empty($assignment['department_id']) ? (int)$assignment['department_id'] : null, $assignment['program_type'] ?? null, $structure),
        'syllabi' => $service->approvedSyllabi((string)$assignment['program_code'], (string)$assignment['course_code']),
        'start' => $assignment['period_start'] ?? '', 'end' => $assignment['period_end'] ?? '',
    ];
}
$lessonItemId = filter_input(INPUT_GET, 'lesson_item', FILTER_VALIDATE_INT) ?: 0;
$lessonItem = null;
if ($plan && $lessonItemId) foreach ($plan['items'] as $candidate) if ((int)$candidate['id'] === $lessonItemId) $lessonItem = $candidate;
$lessonTemplates = $plan ? $service->activeTemplates('lesson_plan') : [];
?>
